// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Optional;
import java.util.OptionalDouble;
import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.leo.LeoEvidence;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.leo.LeoSurfaceKey;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;
import org.eclipse.rdf4j.sail.lmdb.LmdbOperatorFeedbackStats.MutationExtent;
import org.eclipse.rdf4j.sail.lmdb.sketch.SketchSnapshotIdentity;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Mutation decay of learned evidence must be proportional to how much of the store a commit changed (regression-safe
 * learning). Previously every mutating commit halved the whole frontier model, halved every fanout surface and aged all
 * learned confidence by half a half-life, so a trickle of one-statement commits erased everything LEO had learned
 * within a handful of commits (review finding 3.7.5 (a)). A commit that rewrites a large share of the store must still
 * decay by the configured floor, and an unknown extent falls back to that flat decay.
 */
class LmdbProportionalMutationDecayTest {

	private static final SketchSnapshotIdentity IDENTITY = new SketchSnapshotIdentity(0x1234L, 0x5678L, 9L);
	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P1 = VF.createIRI("urn:test:proportional-decay:p1");
	private static final IRI P2 = VF.createIRI("urn:test:proportional-decay:p2");
	private static final long STORE_SIZE = 1_000_000L;
	private static final int TRICKLE_COMMITS = 20;
	private static final long HALF_HALF_LIFE_EPOCHS = 2048L;
	private static final long FANOUT_PREDICATE = 33L;
	private static final long FANOUT_VALUE = 44L;
	private static final long FANOUT = 123L;

	@Test
	void trickleCommitsMustNotEraseTheFrontierModel(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats stats = newStats(tempDir);
		FrontierLearningKey key = learnFrontierCorrection(stats, 61L);
		double before = frontierCorrection(stats, key);
		assertTrue(before > 100.0d, "precondition: the observation shifts the corrected estimate (" + before + ")");

		long stamp = 1L;
		for (int i = 0; i < TRICKLE_COMMITS; i++) {
			stats.recordStoreMutation(++stamp, Set.of(), new MutationExtent(1L, STORE_SIZE));
		}

		OptionalDouble after = frontierCorrectionIfPresent(stats, key);
		assertTrue(after.isPresent(), TRICKLE_COMMITS + " one-statement commits on a " + STORE_SIZE
				+ "-statement store erased the learned frontier correction entirely");
		double retained = (after.getAsDouble() - 100.0d) / (before - 100.0d);
		assertTrue(retained >= 0.9d, TRICKLE_COMMITS + " one-statement commits on a " + STORE_SIZE
				+ "-statement store must keep >= 90% of the learned shift, kept " + retained + " (before=" + before
				+ ", after=" + after.getAsDouble() + ")");
	}

	@Test
	void trickleCommitsMustNotAgeLearnedConfidenceByHalfAHalfLifeEach(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats stats = newStats(tempDir);
		learnFrontierCorrection(stats, 62L);
		long epochBefore = feedbackEpoch(stats);

		long stamp = 1L;
		for (int i = 0; i < TRICKLE_COMMITS; i++) {
			stats.recordStoreMutation(++stamp, Set.of(), new MutationExtent(1L, STORE_SIZE));
		}

		long aged = feedbackEpoch(stats) - epochBefore;
		assertTrue(aged >= TRICKLE_COMMITS, "every mutating commit still advances the feedback epoch (" + aged + ")");
		assertTrue(aged < HALF_HALF_LIFE_EPOCHS,
				TRICKLE_COMMITS + " one-statement commits must age learned confidence by less than ONE bulk rewrite"
						+ " does (" + HALF_HALF_LIFE_EPOCHS + " epochs), aged " + aged);
	}

	@Test
	void trickleCommitsMustNotEraseFanoutSurfaceEvidence(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats stats = newStats(tempDir);
		for (long epoch = 1L; epoch <= 8L; epoch++) {
			stats.recordFanout(FANOUT_PREDICATE, LmdbLeoSurfaceStats.BoundPosition.OBJECT, FANOUT_VALUE, FANOUT,
					epoch);
		}
		LeoEvidence before = fanoutEvidence(stats);
		assertEquals(8L, before.evidenceCount(), "precondition: eight fanout samples are recorded");
		assertEquals(FANOUT, before.rows(), 0.0d);

		long stamp = 1L;
		for (int i = 0; i < TRICKLE_COMMITS; i++) {
			// the mutated predicate IS the learned one: predicate-targeted decay must still be proportional
			stats.recordStoreMutation(++stamp, Set.of(FANOUT_PREDICATE), new MutationExtent(1L, STORE_SIZE));
		}

		LeoEvidence after = fanoutEvidence(stats);
		assertEquals(FANOUT, after.rows(), 0.0d, "decay shrinks the evidence weight, never the learned fanout");
		assertTrue(after.evidenceCount() >= 7L, TRICKLE_COMMITS
				+ " one-statement commits must keep the fanout sample count nearly intact, kept "
				+ after.evidenceCount() + " of 8");
		assertTrue(after.confidence() >= 0.9d * before.confidence(),
				"fanout confidence must keep >= 90% of its value under trickle writes (before=" + before.confidence()
						+ ", after=" + after.confidence() + ")");
	}

	@Test
	void bulkRewriteStillDecaysByTheConfiguredFloor(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats proportional = newStats(tempDir.resolve("proportional"));
		LmdbOperatorFeedbackStats flat = newStats(tempDir.resolve("flat"));
		FrontierLearningKey key = learnFrontierCorrection(proportional, 63L);
		learnFrontierCorrection(flat, 63L);
		long epochBefore = feedbackEpoch(flat);

		// half of the store rewritten in one commit: at or beyond the floor, so exactly today's flat decay applies
		proportional.recordStoreMutation(2L, Set.of(), new MutationExtent(STORE_SIZE / 2L, STORE_SIZE));
		flat.recordStoreMutation(2L, Set.of());

		assertEquals(frontierCorrection(flat, key), frontierCorrection(proportional, key), 1e-9d,
				"a bulk rewrite decays the frontier model exactly like the flat per-commit decay");
		assertEquals(feedbackEpoch(flat) - epochBefore, feedbackEpoch(proportional) - epochBefore,
				"a bulk rewrite ages learned confidence exactly like the flat per-commit decay");
		assertEquals(HALF_HALF_LIFE_EPOCHS, feedbackEpoch(flat) - epochBefore,
				"the flat decay ages learned confidence by half a half-life");
	}

	@Test
	void emptyingTheStoreDecaysFully(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats proportional = newStats(tempDir.resolve("proportional"));
		LmdbOperatorFeedbackStats flat = newStats(tempDir.resolve("flat"));
		FrontierLearningKey key = learnFrontierCorrection(proportional, 64L);
		learnFrontierCorrection(flat, 64L);

		proportional.recordStoreMutation(2L, Set.of(), new MutationExtent(5L, 0L));
		flat.recordStoreMutation(2L, Set.of());

		assertEquals(frontierCorrection(flat, key), frontierCorrection(proportional, key), 1e-9d,
				"deleting everything (total 0) is a full rewrite and decays by the floor");
	}

	@Test
	void unknownExtentFallsBackToFlatDecay(@TempDir Path tempDir) throws Exception {
		LmdbOperatorFeedbackStats proportional = newStats(tempDir.resolve("proportional"));
		LmdbOperatorFeedbackStats flat = newStats(tempDir.resolve("flat"));
		FrontierLearningKey key = learnFrontierCorrection(proportional, 65L);
		learnFrontierCorrection(flat, 65L);
		long epochBefore = feedbackEpoch(flat);

		proportional.recordStoreMutation(2L, Set.of(), MutationExtent.UNKNOWN);
		flat.recordStoreMutation(2L, Set.of());

		assertEquals(frontierCorrection(flat, key), frontierCorrection(proportional, key), 1e-9d);
		assertEquals(feedbackEpoch(flat) - epochBefore, feedbackEpoch(proportional) - epochBefore);
	}

	@Test
	void killSwitchRestoresFlatDecayForTrickleCommits(@TempDir Path tempDir) throws Exception {
		String previous = System.getProperty(LmdbOperatorFeedbackStats.MUTATION_DECAY_PROPORTIONAL_PROPERTY);
		System.setProperty(LmdbOperatorFeedbackStats.MUTATION_DECAY_PROPORTIONAL_PROPERTY, "false");
		try {
			LmdbOperatorFeedbackStats proportional = newStats(tempDir.resolve("proportional"));
			LmdbOperatorFeedbackStats flat = newStats(tempDir.resolve("flat"));
			FrontierLearningKey key = learnFrontierCorrection(proportional, 66L);
			learnFrontierCorrection(flat, 66L);
			long epochBefore = feedbackEpoch(flat);

			proportional.recordStoreMutation(2L, Set.of(), new MutationExtent(1L, STORE_SIZE));
			flat.recordStoreMutation(2L, Set.of());

			assertEquals(frontierCorrection(flat, key), frontierCorrection(proportional, key), 1e-9d,
					"with the kill switch a one-statement commit halves the frontier model like before");
			assertEquals(feedbackEpoch(flat) - epochBefore, feedbackEpoch(proportional) - epochBefore);
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbOperatorFeedbackStats.MUTATION_DECAY_PROPORTIONAL_PROPERTY);
			} else {
				System.setProperty(LmdbOperatorFeedbackStats.MUTATION_DECAY_PROPORTIONAL_PROPERTY, previous);
			}
		}
	}

	private static LmdbOperatorFeedbackStats newStats(Path dir) throws Exception {
		Path estimatorPath = dir.resolve("join-estimator.rjes");
		Files.createDirectories(estimatorPath);
		Files.writeString(estimatorPath.resolve("metadata.bin"), "metadata");
		return new LmdbOperatorFeedbackStats(estimatorPath, () -> IDENTITY, () -> true, () -> 1L);
	}

	private static FrontierLearningKey learnFrontierCorrection(LmdbOperatorFeedbackStats stats, long keySeed) {
		FrontierLearningKey key = FrontierLearningKey.of(
				"join", "JOIN", keySeed, 13L, "spoc-prefix", "spoc", "prefix");
		Join observed = new Join(sp("s", P1, "x"), sp("x", P2, "o"));
		completeCostFeedback(observed, 51_200L, 100.0d, 100.0d, 51_200.0d);
		observed.setStringMetricPlanned("optimizer.frontierLearningKey", key.externalForm());
		observed.setStringMetricPlanned("optimizer.costEventDigest", "event-" + keySeed);
		observed.setStringMetricPlanned("optimizer.frontierStateDigest", "state-" + keySeed);
		observed.setStringMetricPlanned("plannedFrontierGuarantee", "measure_unbiased");
		observed.setDoubleMetricPlanned("optimizer.costEventRows", 100.0d);
		stats.recordOperatorOutcome(observed);
		return key;
	}

	private static void completeCostFeedback(TupleExpr node, long actualRows, double plannedRows,
			double plannedWorkRows, double actualWorkRows) {
		node.setCostFeedbackTrackingEnabled(true);
		node.setCostFeedbackExpectedRows(plannedRows);
		node.setCostFeedbackExpectedWorkRows(plannedWorkRows);
		node.setCostFeedbackReportQErrorThreshold(LmdbOperatorFeedbackStats.DEFAULT_REPORT_Q_ERROR_THRESHOLD);
		node.setResultSizeEstimate(plannedRows);
		node.setCostEstimate(plannedWorkRows);
		node.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, plannedWorkRows);
		node.setCostFeedbackActualRows(actualRows);
		node.setCostFeedbackActualWorkRows(actualWorkRows);
		node.setCostFeedbackCloseCountActual(1L);
		node.setCostFeedbackCompletedActual(true);
		node.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1);
	}

	private static StatementPattern sp(String subjectName, IRI predicate, String objectName) {
		return new StatementPattern(Var.of(subjectName), Var.of("_p", predicate, true, true), Var.of(objectName));
	}

	private static LeoEvidence fanoutEvidence(LmdbOperatorFeedbackStats stats) {
		Optional<LeoEvidence> evidence = stats
				.evidence(LeoSurfaceKey.fanout(FANOUT_PREDICATE, "object", FANOUT_VALUE));
		assertTrue(evidence.isPresent(), "fanout evidence must be present");
		return evidence.get();
	}

	private static double frontierCorrection(LmdbOperatorFeedbackStats stats, FrontierLearningKey key)
			throws Exception {
		OptionalDouble correction = frontierCorrectionIfPresent(stats, key);
		assertTrue(correction.isPresent(), "the observed frontier dimension must have a posterior correction");
		return correction.getAsDouble();
	}

	private static OptionalDouble frontierCorrectionIfPresent(LmdbOperatorFeedbackStats stats,
			FrontierLearningKey key) throws Exception {
		Method method = LmdbOperatorFeedbackStats.class.getDeclaredMethod("frontierCorrection",
				FrontierLearningKey.class, FrontierCostDimension.class, double.class, boolean.class);
		method.setAccessible(true);
		Object value = method.invoke(stats, key, FrontierCostDimension.OUTPUT_ROWS, 100.0d, false);
		assertTrue(value instanceof OptionalDouble, "frontierCorrection must expose an optional correction");
		return (OptionalDouble) value;
	}

	private static long feedbackEpoch(LmdbOperatorFeedbackStats stats) throws Exception {
		Field field = LmdbOperatorFeedbackStats.class.getDeclaredField("feedbackEpoch");
		field.setAccessible(true);
		return field.getLong(stats);
	}
}
